import"./chunk-7CGTOI24.js";var a={slug:"review-donkey-kong-bananza",title:"Review: Donkey Kong Bananza transforma destrui\xE7\xE3o em divers\xE3o pura",dek:"Quebrar tudo \xE9 a regra no grande 3D do Donkey Kong para Switch 2. Revisitamos o jogo com a biblioteca do console mais madura.",section:"games",kind:"review",tags:["Nintendo","Switch 2","Plataforma"],date:"2026-10-30",hero:{ref:"game:338106",pick:0,alt:"Donkey Kong em arte de Donkey Kong Bananza"},score:8.5,verdict:{summary:"Um jogo de plataforma que faz da destrui\xE7\xE3o o seu verbo principal. \xC0s vezes a c\xE2mera se perde no caos, mas a sensa\xE7\xE3o de cavar o mundo com as pr\xF3prias m\xE3os \xE9 \xFAnica.",good:["Destrui\xE7\xE3o do cen\xE1rio como mec\xE2nica central","Transforma\xE7\xF5es Bananza variadas e divertidas","\xD3timo para jogar em sess\xF5es curtas"],bad:["C\xE2mera atrapalha em espa\xE7os apertados","Algumas fases se estendem al\xE9m da conta"]},body:[{p:"Quando *Donkey Kong Bananza* saiu, em 17 de julho de 2025, o Switch 2 tinha pouco mais de um m\xEAs de vida. Hoje, com a biblioteca do console bem mais cheia, a pergunta \xE9 se ele ainda se destaca. A resposta curta: sim, e por um motivo que nenhum outro jogo da plataforma copia."},{ficha:"game:338106"},{h2:"O mundo \xE9 feito para quebrar"},{p:"Quase tudo em *Bananza* pode ser socado, arrancado ou atravessado. Donkey Kong cava t\xFAneis, arranca peda\xE7os do ch\xE3o para usar como arma ou prancha e abre caminhos que n\xE3o existiam. A explora\xE7\xE3o deixa de ser s\xF3 seguir uma trilha e vira uma pergunta constante: o que tem atr\xE1s dessa parede?"},{p:"A estrutura em camadas refor\xE7a a ideia. Voc\xEA desce cada vez mais fundo no planeta, e cada n\xEDvel tem regras e materiais diferentes, alguns f\xE1ceis de quebrar, outros resistentes, outros perigosos."},{img:"game:338106",pick:2,caption:"Cada camada tem materiais e regras pr\xF3prias. Imagem de divulga\xE7\xE3o."},{h2:"Pauline e as transforma\xE7\xF5es"},{p:"Pauline, em uma vers\xE3o jovem, acompanha DK na aventura, e sua voz \xE9 o que destrava as transforma\xE7\xF5es Bananza. Cada forma muda o jeito de jogar, seja para destruir mais r\xE1pido, alcan\xE7ar lugares altos ou atravessar \xE1reas que seriam imposs\xEDveis de outro modo. \xC9 um sistema simples que mant\xE9m o jogo variado do come\xE7o ao fim."},{quote:"Bananza \xE9 a rara ideia de design que parece \xF3bvia depois que voc\xEA joga: por que n\xE3o deixar o macaco quebrar tudo?"},{h2:"Onde ele trope\xE7a"},{p:"Tanto caos tem custo. Em t\xFAneis estreitos, a c\xE2mera \xE0s vezes n\xE3o sabe para onde olhar, e \xE9 f\xE1cil perder a no\xE7\xE3o de dire\xE7\xE3o depois de cavar por muito tempo. Algumas fases tamb\xE9m se estendem al\xE9m do necess\xE1rio, com objetivos repetidos."},{h2:"Veredito"},{p:"*Donkey Kong Bananza* \xE9 uma das experi\xEAncias mais originais do Switch 2 e combina muito bem com sess\xF5es curtas no modo port\xE1til. N\xE3o \xE9 perfeito, mas \xE9 o tipo de jogo que s\xF3 a Nintendo arriscaria fazer. Nota 8,5."},{p:"Montando a biblioteca do console? Veja nossa lista de [jogos essenciais do Switch 2](/artigo/switch-2-jogos-essenciais)."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{338106:{id:338106,name:"Donkey Kong Bananza",type:"Jogo principal",cover:"cobd1q",shots:["scw2wn","scw2wo","scw2wp","scw2wq","scw2wr"],arts:["ar3p81"],genres:["Plataforma","Aventura","A\xE7\xE3o"],modes:["Single player","Multiplayer"],devs:["Nintendo EPD Production Group No. 8"],pubs:["Nintendo"],released:"2025-07-17",releases:{"Switch 2":"2025-07-17"},classInd:"L"}},movies:{},tv:{}};export{o as media,a as post};
